def buggy_search(xs, target):
    lo, hi = 0, len(xs) - 1
    steps = 0
    while lo <= hi:
        steps += 1
        if steps > 20:
            return f'HANG: loop exceeded 20 iterations (lo={lo}, hi={hi})'
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        elif xs[mid] < target:
            lo = mid  # bug: does not move past mid
        else:
            hi = mid - 1
    return -1

print(buggy_search([2, 5, 8, 12, 16, 23], 23))

def search(xs, target):
    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        elif xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

xs = [2, 5, 8, 12, 16, 23]
print([search(xs, v) for v in xs])
print('absent 7 ->', search(xs, 7))

import functools

def counted(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return fn(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@counted
def greet(name):
    return f'Hello, {name}'

print(greet('Ana'))
print(greet('Ben'))
print(greet('Ana'))
print('calls:', greet.calls)
print('name preserved:', greet.__name__)

