import re

def tokenize(text):
    return re.findall(r'\d+|[()+\-*/]', text)

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None
    def take(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok
    def expr(self):
        value = self.term()
        while self.peek() in ('+', '-'):
            op = self.take()
            rhs = self.term()
            value = value + rhs if op == '+' else value - rhs
        return value
    def term(self):
        value = self.factor()
        while self.peek() in ('*', '/'):
            op = self.take()
            rhs = self.factor()
            value = value * rhs if op == '*' else value / rhs
        return value
    def factor(self):
        tok = self.take()
        if tok == '(':
            value = self.expr()
            self.take()  # closing paren
            return value
        return int(tok)

def evaluate(text):
    return Parser(tokenize(text)).expr()

for e in ('2 + 3 * 4', '(2 + 3) * 4', '18 / (3 + 3)', '7 - 2 - 1'):
    print(e, '=', evaluate(e))

