from dataclasses import dataclass

@dataclass
class Booking:
    guest: str
    nights: int
    rate: float
    def __post_init__(self):
        if self.nights < 1:
            raise ValueError('nights must be at least 1')
        if self.rate <= 0:
            raise ValueError('rate must be positive')
    def total(self):
        return self.nights * self.rate

good = Booking('Ana Ruiz', 3, 120.0)
print('valid booking total:', good.total())
for guest, nights, rate in (('Ben Cole', 0, 120.0), ('Cleo Tan', 2, -50.0)):
    try:
        Booking(guest, nights, rate)
        print(guest, 'ACCEPTED (unexpected)')
    except ValueError as e:
        print(guest, 'rejected:', e)

